var n=`0071-lecso`;var i=`world-0071`;var s=`HU`;var o=`eastern-europe`;var a=4;var r=36;var l={en:`Lecsó`,ua:`Лечо`};var g={en:`A classic dish from Hungary, featuring yellow onion, red bell pepper, tomato, chicken egg. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Угорщина. Основні складники: жовта цибуля, червоний солодкий перець, помідор, куряче яйце. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,160,`g`],[`red-bell-pepper`,420,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 20 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 20 хвилин до м’якості та готовності.`,t:[`simmering`],m:20,i:[[`tomato`,570,`g`],[`sweet-paprika`,12,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`chicken-egg`,3,`pcs`]]}];var u={slug:n,id:i,country:`HU`,region:o,servings:4,minutes:36,title:l,text:g,steps:d};export{s as country,u as default,i as id,r as minutes,o as region,a as servings,n as slug,d as steps,g as text,l as title};